            const options: HTMLElement[] = Array.prototype.slice.call(reference.querySelectorAll('[data-config-reference-option]'));
            const status = reference.querySelector<HTMLElement>('#configuration-reference-status');
            const empty = reference.querySelector<HTMLElement>('#configuration-reference-empty');
