                    const entries: HTMLElement[] = Array.prototype.slice.call(group.querySelectorAll('[data-config-reference-option]'));
                    const hidden = !!query && !entries.some((entry) => !entry.hidden);
                    // The disclosure owner intentionally ignores hidden details. Synchronize its content first.
